def sh(c):
    r = subprocess.run(c, shell=True, capture_output=True, text=True); print("$", c[:100], "->", r.returncode, (r.stdout + r.stderr)[-800:], flush=True); return r.returncode
PY = "/tmp/venv/bin/python"; UV = f"{sys.executable} -m uv"
for c in ("pip install -q uv", f"{UV} python install 3.12", f"{UV} venv -p 3.12 /tmp/venv",
          f"{UV} pip install --python {PY} --index-url https://download.pytorch.org/whl/cpu torch==2.3.1",
          f"{UV} pip install --python {PY} numpy==1.26.4 transformers==4.44.2 tokenizers==0.19.1 sentence-transformers==3.0.1 "
          f"huggingface_hub==0.24.7 spacy==3.8.16 mpmath https://github.com/explosion/spacy-models/releases/download/en_core_web_sm-3.8.0/en_core_web_sm-3.8.0-py3-none-any.whl"):
    if sh(c): json.dump({"stopped": c[:60]}, open("STATUS.json", "w")); sys.exit(0)
dl = ("import os\nfrom huggingface_hub import snapshot_download\nhub=os.path.expanduser('~/.cache/huggingface/hub')\n"
      "for repo, rev in (('Qwen/Qwen2.5-1.5B-Instruct','989aa7980e4cf806f80c7fef2b1adb7bc71aa306'),('sentence-transformers/all-MiniLM-L6-v2','1110a243fdf4706b3f48f1d95db1a4f5529b4d41')):\n"
      "    snapshot_download(repo, revision=rev)\n    d=os.path.join(hub,'models--'+repo.replace('/','--'),'refs'); os.makedirs(d, exist_ok=True)\n    open(os.path.join(d,'main'),'w').write(rev)\n")
if subprocess.run([PY, "-c", dl]).returncode: json.dump({"stopped": "models"}, open("STATUS.json", "w")); sys.exit(0)
r = subprocess.run([PY, "q3_v05.py", "../q3_kaggle.json"], cwd="build", capture_output=True, text=True)
